 assert p.exists(),p
 shutil.copy2(p,r/(label+'.log'));records[label]={'finished_at':datetime.datetime.fromtimestamp(p.stat().st_mtime,datetime.timezone.utc).isoformat(),'log':label+'.log','bytes':p.stat().st_size}
